namespace Dcs.Ipia.Tests;

public sealed class PhaseOneDomainTests {
 private static readonly Guid ProfileId=Guid.Parse("aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa");
 [Fact] public void Stable_identity_is_deterministic_and_scoped(){var first=StableIdentity.Create("UH-1H","tm-mfd\0MFD1");Assert.Equal(first,StableIdentity.Create(" UH-1H "," tm-mfd\0MFD1 "));Assert.NotEqual(first,StableIdentity.Create("UH-1H","tm-mfd\0MFD2"));Assert.Throws<ArgumentException>(()=>StableIdentity.Create("","x"));Assert.Throws<ArgumentException>(()=>StableIdentity.Create("x"," "));}
 [Fact] public void Records_normalize_values(){var profile=new DeviceProfile(ProfileId," tm-mfd "," MFD1 "," panel "," source.lua ");var modifier=new DcsModifier(" Shift "," Stick "," BTN3 ",ModifierMode.Hold);var binding=new DcsBinding(ProfileId,BindingSection.Axis," axis "," Roll ",BindingDisposition.Changed," JOY_X ",["Shift"],new(Invert:true));Assert.Equal("tm-mfd",profile.DeviceId);Assert.Equal("MFD1",profile.Instance);Assert.Equal("Shift",modifier.Name);Assert.Equal("axis",binding.CommandId);Assert.True(binding.Filter!.Invert is true);}
 [Fact] public void Invalid_records_are_rejected(){Assert.Throws<ArgumentException>(()=>new DeviceProfile(Guid.Empty,"x",null,"r","s"));Assert.Throws<ArgumentException>(()=>new DeviceProfile(ProfileId,"","", "r","s"));Assert.Throws<ArgumentException>(()=>new DeviceProfile(ProfileId,"x",null,"","s"));Assert.Throws<ArgumentException>(()=>new DeviceProfile(ProfileId,"x",null,"r",""));Assert.Throws<ArgumentException>(()=>new DcsModifier("","d","k",ModifierMode.Hold));Assert.Throws<ArgumentException>(()=>new DcsModifier("m","","k",ModifierMode.Hold));Assert.Throws<ArgumentException>(()=>new DcsModifier("m","d","",ModifierMode.Hold));Assert.Throws<ArgumentException>(()=>new DcsBinding(Guid.Empty,BindingSection.Key,"c","n",BindingDisposition.Added,"k"));Assert.Throws<ArgumentException>(()=>new DcsBinding(ProfileId,BindingSection.Key,"c","n",BindingDisposition.Added,"k",filter:new(Invert:true)));Assert.Throws<ArgumentException>(()=>new DcsBinding(ProfileId,BindingSection.Key,"","n",BindingDisposition.Added,"k"));Assert.Throws<ArgumentException>(()=>new DcsBinding(ProfileId,BindingSection.Key,"c","",BindingDisposition.Added,"k"));Assert.Throws<ArgumentException>(()=>new DcsBinding(ProfileId,BindingSection.Key,"c","n",BindingDisposition.Added,""));Assert.Throws<ArgumentException>(()=>new DcsBinding(ProfileId,BindingSection.Key,"c","n",BindingDisposition.Added,"k",["A","A"]));}
 [Fact] public void Configuration_enforces_identity_and_reference_integrity(){var module=new DcsModule(Guid.NewGuid(),"UH-1H","Huey");var profile=new DeviceProfile(ProfileId,"mfd","MFD1","panel","mfd.lua");var modifier=new DcsModifier("Shift","Stick","BTN3",ModifierMode.Hold);var binding=new DcsBinding(ProfileId,BindingSection.Key,"c","Command",BindingDisposition.Added,"BTN1",["Shift"]);var value=new ModuleConfiguration(module,[profile],[modifier],[binding],"repo@sha");Assert.Equal("repo@sha",value.Provenance);Assert.Throws<ArgumentNullException>(()=>new ModuleConfiguration(null!,[],[],[],"p"));Assert.Throws<ArgumentNullException>(()=>new ModuleConfiguration(module,null!,[],[],"p"));Assert.Throws<ArgumentNullException>(()=>new ModuleConfiguration(module,[],null!,[],"p"));Assert.Throws<ArgumentNullException>(()=>new ModuleConfiguration(module,[],[],null!,"p"));Assert.Throws<ArgumentException>(()=>new ModuleConfiguration(module,[profile,profile],[],[],"p"));Assert.Throws<ArgumentException>(()=>new ModuleConfiguration(module,[profile,new(Guid.NewGuid(),"MFD","mfd1","panel","two")],[],[],"p"));Assert.Throws<ArgumentException>(()=>new ModuleConfiguration(module,[profile],[modifier,new("shift","Other","BTN4",ModifierMode.Hold)],[],"p"));Assert.Throws<ArgumentException>(()=>new ModuleConfiguration(module,[profile],[modifier,new("Other","stick","btn3",ModifierMode.Hold)],[],"p"));Assert.Throws<ArgumentException>(()=>new ModuleConfiguration(module,[profile],[],[binding],"p"));Assert.Throws<ArgumentException>(()=>new ModuleConfiguration(module,[profile],[modifier],[new(Guid.NewGuid(),BindingSection.Key,"c","n",BindingDisposition.Added,"k")],"p"));Assert.Throws<ArgumentException>(()=>new ModuleConfiguration(module,[profile],[],[],""));}
}

public sealed class LuaImportTests {
 private static readonly Guid ProfileId=Guid.Parse("aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa");
 private const string Profile="""
local diff = {
["keyDiffs"] = {
 ["d1"] = { ["added"] = { [1] = { ["key"] = "JOY_BTN1", ["reformers"] = { [1] = "SHIFT" } }, }, ["removed"] = { [1] = { ["key"] = "JOY_BTN2" }, }, ["name"] = "Fire \"weapon\"", },
},
["axisDiffs"] = {
 ["a1"] = { ["changed"] = { [1] = { ["key"] = "JOY_X", ["filter"] = { ["deadzone"] = .1, ["saturationX"] = 1, ["saturationY"] = .9, ["curvature"] = { [1] = -0.2, [2] = 0.2 }, ["invert"] = true, ["slider"] = false, ["hardwareDetent"] = true, ["hardwareDetentAB"] = .7, ["hardwareDetentMax"] = .95 } }, }, ["name"] = "Roll", },
},}
return diff
""";
 private const string Modifiers="""
local modifiers = { ["SHIFT"] = { ["device"] = "MOZA", ["key"] = "JOY_BTN3", ["switch"] = false, }, ["MODE"] = { ["device"] = "Throttle", ["key"] = "JOY_BTN4", ["switch"] = true, }, }
return modifiers
""";
 [Fact] public void Parser_preserves_added_removed_changed_filters_and_chords(){var values=DcsLuaParser.ParseProfile(Profile,ProfileId);Assert.Equal(3,values.Count);var added=Assert.Single(values.Where(x=>x.Disposition==BindingDisposition.Added));Assert.Equal("Fire \"weapon\"",added.CommandName);Assert.Equal(["SHIFT"],added.Reformers);Assert.Single(values.Where(x=>x.Disposition==BindingDisposition.Removed));var axis=Assert.Single(values.Where(x=>x.Disposition==BindingDisposition.Changed));Assert.Equal(BindingSection.Axis,axis.Section);Assert.Equal([-.2,.2],axis.Filter!.Curvature);Assert.True(axis.Filter.Invert is true);Assert.True(axis.Filter.Slider is false);Assert.Equal(.95,axis.Filter.HardwareDetentMax);}
 [Fact] public void Modifier_parser_preserves_modes(){var values=DcsLuaParser.ParseModifiers(Modifiers);Assert.Equal(["MODE","SHIFT"],values.Select(x=>x.Name));Assert.Equal(ModifierMode.Toggle,values[0].Mode);Assert.Equal(ModifierMode.Hold,values[1].Mode);}
 [Theory]
 [InlineData("local diff = {}","return the diff")]
 [InlineData("local diff = { [\"keyDiffs\"] = { [\"c\"] = { [\"added\"] = { [1] = { [\"key\"] = \"K\" } } } } } return diff","has no name")]
 [InlineData("local diff = { [\"keyDiffs\"] = { [\"c\"] = { [\"added\"] = { [1] = { } }, [\"name\"] = \"N\" } } } return diff","has no key")]
 [InlineData("local diff = {","return the diff")]
 public void Invalid_profiles_report_actionable_errors(string source,string message)=>Assert.Contains(message,Assert.Throws<FormatException>(()=>DcsLuaParser.ParseProfile(source,ProfileId)).Message,StringComparison.Ordinal);
 [Fact] public void Invalid_profile_arguments_are_rejected(){Assert.Throws<ArgumentException>(()=>DcsLuaParser.ParseProfile("",ProfileId));Assert.Throws<ArgumentException>(()=>DcsLuaParser.ParseProfile("return diff",Guid.Empty));Assert.Throws<FormatException>(()=>DcsLuaParser.ParseProfile("local diff = { [\"keyDiffs\"] = { return diff",ProfileId));}
 [Theory]
 [InlineData("local modifiers = {}","return the modifiers")]
 [InlineData("return modifiers","declare local modifiers")]
 [InlineData("local modifiers = { [\"M\"] = { [\"device\"] = \"D\" } } return modifiers","requires device")]
 [InlineData("local modifiers = { [\"M\"] = { [\"device\"] = \"D\", [\"key\"] = \"K\", [\"switch\"] = false }, [\"m\"] = { [\"device\"] = \"D2\", [\"key\"] = \"K2\", [\"switch\"] = true } } return modifiers","unique ignoring case")]
 [InlineData("local modifiers = { [\"M\"] = { [\"device\"] = \"D\", [\"key\"] = \"K\", [\"switch\"] = false }, [\"N\"] = { [\"device\"] = \"d\", [\"key\"] = \"k\", [\"switch\"] = true } } return modifiers","physical inputs")]
 public void Invalid_modifiers_report_actionable_errors(string source,string message)=>Assert.Contains(message,Assert.Throws<FormatException>(()=>DcsLuaParser.ParseModifiers(source)).Message,StringComparison.Ordinal);
 [Fact] public async Task Importer_is_idempotent_and_reports_source_errors(){var module=new DcsModule(Guid.Parse("11111111-1111-1111-1111-111111111111"),"UH-1H","Huey");var request=new ModuleImportRequest(module,[new("tm-mfd","MFD1","panel","mfd.lua",Profile)],Modifiers,"Huey@abc");var importer=new DcsLuaImporter();var first=await importer.ImportAsync(request);var second=await importer.ImportAsync(request);Assert.True(first.Succeeded);Assert.Equal(ConfigurationSnapshotSerializer.Serialize([first.Configuration!]).Content,ConfigurationSnapshotSerializer.Serialize([second.Configuration!]).Content);Assert.Contains(first.Diagnostics,x=>x.Code=="imported"&&!x.IsError);var badModifiers=await importer.ImportAsync(request with{ModifiersContent="bad"});Assert.False(badModifiers.Succeeded);Assert.Equal("invalid-modifiers",Assert.Single(badModifiers.Diagnostics).Code);var badProfile=await importer.ImportAsync(request with{Profiles=[new("d",null,"r","bad.lua","bad")]});Assert.False(badProfile.Succeeded);Assert.Equal("invalid-profile",Assert.Single(badProfile.Diagnostics).Code);await Assert.ThrowsAnyAsync<OperationCanceledException>(()=>importer.ImportAsync(request,new(true)));}
}

public sealed class PhaseOneApplicationTests {
 [Fact] public async Task Service_persists_only_successful_imports(){var configuration=Fixture();var repository=new MemoryConfigurationRepository();var importer=new StubImporter(new(configuration,[]));var service=new ConfigurationImportService(importer,repository);Assert.True((await service.ImportAsync(Request())).Succeeded);Assert.Equal(configuration,await repository.GetAsync(configuration.Module.Id));importer.Result=new(null,[new("bad","bad",true)]);Assert.False((await service.ImportAsync(Request())).Succeeded);Assert.Equal(1,repository.Writes);await Assert.ThrowsAsync<ArgumentNullException>(()=>service.ImportAsync(null!));}
 private static ModuleConfiguration Fixture(){var module=new DcsModule(Guid.NewGuid(),"UH-1H","Huey");return new(module,[],[],[],"test");}
 private static ModuleImportRequest Request()=>new(new(Guid.NewGuid(),"UH-1H","Huey"),[],null,"test");
 private sealed class StubImporter(ModuleImportResult result):IModuleConfigurationImporter {public ModuleImportResult Result{get;set;}=result;public Task<ModuleImportResult> ImportAsync(ModuleImportRequest request,CancellationToken ct=default)=>Task.FromResult(Result);}
 private sealed class MemoryConfigurationRepository:IModuleConfigurationRepository {private readonly Dictionary<Guid,ModuleConfiguration> values=[];public int Writes{get;private set;}public Task<ModuleConfiguration?> GetAsync(Guid id,CancellationToken ct=default)=>Task.FromResult(values.GetValueOrDefault(id));public Task<IReadOnlyList<ModuleConfiguration>> ListAsync(CancellationToken ct=default)=>Task.FromResult<IReadOnlyList<ModuleConfiguration>>(values.Values.ToArray());public Task ReplaceAsync(ModuleConfiguration value,CancellationToken ct=default){Writes++;values[value.Module.Id]=value;return Task.CompletedTask;}}
}

public sealed class SnapshotTests {
 [Fact] public void Full_snapshot_is_deterministic_hashed_and_lossless(){var huey=Fixture("UH-1H","Huey",1);var tomcat=Fixture("F-14","Tomcat",2);var first=ConfigurationSnapshotSerializer.Serialize([huey,tomcat]);var second=ConfigurationSnapshotSerializer.Serialize([tomcat,huey]);Assert.Equal(first,second);Assert.Equal(64,first.Sha256.Length);var restored=ConfigurationSnapshotSerializer.Deserialize(first.Content);Assert.Equal(first.Content,ConfigurationSnapshotSerializer.Serialize(restored).Content);Assert.EndsWith("\n",first.Content,StringComparison.Ordinal);}
 [Fact] public void Snapshot_rejects_invalid_content(){Assert.Throws<ArgumentNullException>(()=>ConfigurationSnapshotSerializer.Serialize(null!));Assert.Throws<ArgumentException>(()=>ConfigurationSnapshotSerializer.Deserialize(""));Assert.Throws<JsonException>(()=>ConfigurationSnapshotSerializer.Deserialize("null"));Assert.Throws<JsonException>(()=>ConfigurationSnapshotSerializer.Deserialize("{\"schemaVersion\":99,\"modules\":[]}"));}
 private static ModuleConfiguration Fixture(string dcs,string name,int seed){var id=new Guid(seed,0,0,new byte[8]);var profile=new DeviceProfile(new Guid(seed+10,0,0,new byte[8]),"tm-mfd",$"MFD{seed}","panel","profile.lua");return new(new(id,dcs,name),[profile],[],[new(profile.Id,BindingSection.Key,"c","Command",BindingDisposition.Added,"JOY_BTN1")],$"repo@{seed}");}
}

public sealed class PhaseOneInfrastructureTests:IDisposable {
 private readonly string path=Path.Combine(Path.GetTempPath(),$"dcs-ipia-phase1-{Guid.NewGuid():N}.db");private string Connection=>$"Data Source={path}";
 [Fact] public async Task Real_sqlite_round_trips_and_replaces_configuration(){await new SqliteMigrationRunner(Connection).MigrateAsync();await new SqliteMigrationRunner(Connection).MigrateAsync();var repository=new SqliteConfigurationRepository(Connection);var value=Fixture("first");Assert.Null(await repository.GetAsync(value.Module.Id));await repository.ReplaceAsync(value);Assert.Equal(ConfigurationSnapshotSerializer.Serialize([value]).Content,ConfigurationSnapshotSerializer.Serialize([await repository.GetAsync(value.Module.Id)??throw new InvalidOperationException()]).Content);Assert.Single(await repository.ListAsync());var replacement=Fixture("second");await repository.ReplaceAsync(replacement);var restored=await repository.GetAsync(value.Module.Id);Assert.Equal("second",restored!.Provenance);Assert.Single(restored.Bindings);Assert.True(restored.Bindings[0].Filter!.Invert is true);Assert.Empty((await repository.ListAsync()).Where(x=>x.Module.DcsId!="UH-1H"));}
 [Fact] public async Task V1_database_migrates_transactionally(){await using(var c=new SqliteConnection(Connection)){await c.OpenAsync();var cmd=c.CreateCommand();cmd.CommandText="CREATE TABLE schema_migrations(version INTEGER NOT NULL PRIMARY KEY,applied_utc TEXT NOT NULL);CREATE TABLE modules(id TEXT NOT NULL PRIMARY KEY,dcs_id TEXT NOT NULL UNIQUE COLLATE NOCASE,display_name TEXT NOT NULL);INSERT INTO schema_migrations VALUES(1,'now');";await cmd.ExecuteNonQueryAsync();}await new SqliteMigrationRunner(Connection).MigrateAsync();await using var migrated=new SqliteConnection(Connection);await migrated.OpenAsync();var check=migrated.CreateCommand();check.CommandText="SELECT COUNT(*) FROM schema_migrations";Assert.Equal(2L,await check.ExecuteScalarAsync());}
 private static ModuleConfiguration Fixture(string provenance){var module=new DcsModule(Guid.Parse("11111111-1111-1111-1111-111111111111"),"UH-1H","Huey");var profile=new DeviceProfile(Guid.Parse("22222222-2222-2222-2222-222222222222"),"moza-ab9-hornet-grip",null,"cyclic","MOZA.diff.lua");var modifier=new DcsModifier("SHIFT","MOZA","JOY_BTN3",ModifierMode.Hold);var binding=new DcsBinding(profile.Id,BindingSection.Axis,"a1","Roll",BindingDisposition.Added,"JOY_X",["SHIFT"],new(Invert:true,Curvature:[-.1,.1]));return new(module,[profile],[modifier],[binding],provenance);}
 public void Dispose(){File.Delete(path);GC.SuppressFinalize(this);}
}
